(2045, 2655, '_elementor_data', '[{\"id\":\"64221eb\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_wrap\":\"wrap\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"}},\"elements\":[{\"id\":\"97c50d5\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":24},\"_flex_size\":\"none\",\"_element_width\":\"initial\"},\"elements\":[{\"id\":\"719587a\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/vi-mach.png\",\"id\":2657,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"774ba2d\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":60.927},\"_flex_size\":\"none\",\"_element_width\":\"initial\"},\"elements\":[{\"id\":\"c175817\",\"elType\":\"widget\",\"settings\":{\"title\":\"V\\u1ec9 m\\u1ea1ch\",\"align\":\"center\",\"title_color\":\"#FF0000\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"3db3818\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Gi\\u00e1: 500.000 VND<\\/p>\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":41,\"sizes\":[]},\"text_color\":\"#FF0000\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"c2fee5e\",\"elType\":\"widget\",\"settings\":{\"text\":\"Th\\u00eam v\\u00e0o gi\\u1ecf h\\u00e0ng\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":29,\"sizes\":[]},\"link\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/gio-hang\\/?add_to_cart=LK_1\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":true},{\"id\":\"4c1c712\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"100\"}},\"elements\":[{\"id\":\"3a25018\",\"elType\":\"widget\",\"settings\":{\"title\":\"\\nTh\\u00f4ng tin s\\u1ea3n ph\\u1ea9m\",\"align\":\"center\",\"title_color\":\"#FF0000\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"b59b912\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p><em>1. V\\u1ec9 m\\u1ea1ch t\\u1ea1o t\\u00edn hi\\u1ec7u \\u0111i\\u1ec1u khi\\u1ec3n c\\u00f2i \\u0111\\u00e8n s\\u01b0\\u01a1ng m\\u00f9<\\/em><\\/p><p>V\\u1ec9 m\\u1ea1ch t\\u1ea1o t\\u00edn hi\\u1ec7u \\u0111i\\u1ec1u khi\\u1ec3n c\\u00f2i \\u0111\\u00e8n s\\u01b0\\u01a1ng m\\u00f9 c\\u00f3 ch\\u1ee9c n\\u0103ng t\\u1ea1o t\\u00edn hi\\u1ec7u \\u0111i\\u1ec1u khi\\u1ec3n \\u0111\\u01b0a sang h\\u1ec7 th\\u1ed1ng c\\u00f2i \\u0111\\u00e8n s\\u01b0\\u01a1ng m\\u00f9 tr\\u00ean t\\u00e0u thu\\u1ef7. V\\u1ec9 m\\u1ea1ch c\\u00f3 c\\u00e1c \\u0111\\u1ea7u v\\u00e0o cho ph\\u00e9p l\\u1ef1a ch\\u1ecdn c\\u00e1c ch\\u1ebf \\u0111\\u1ed9 l\\u00e0m vi\\u1ec7c kh\\u00e1c nhau. M\\u1ed7i m\\u1ed9t ch\\u1ebf \\u0111\\u1ed9 l\\u00e0m vi\\u1ec7c v\\u1ec9 m\\u1ea1ch l\\u1ea1i t\\u1ef1 \\u0111\\u1ed9ng t\\u1ea1o ra m\\u1ed9t chu tr\\u00ecnh t\\u00edn hi\\u1ec7u \\u0111i\\u1ec1u khi\\u1ec3n c\\u00f2i \\u0111\\u00e8n s\\u01b0\\u01a1ng m\\u00f9 ph\\u00f9 h\\u1ee3p theo quy \\u0111\\u1ecbnh c\\u1ee7a t\\u00edn hi\\u1ec7u c\\u00f2i \\u0111\\u00e8n s\\u01b0\\u01a1ng m\\u00f9 tr\\u00ean t\\u00e0u bi\\u1ec3n.<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"f705d97\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/vi-mach-1.png\",\"id\":2658,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"3832b1a\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p><em>2. V\\u1ec9 m\\u1ea1ch \\u0111o v\\u00e0 hi\\u1ec3n th\\u1ecb t\\u1ed1c \\u0111\\u1ed9 m\\u00e1y t\\u00e0u thu\\u1ef7<\\/em><\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"a438d73\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/vi-mach-2.jpg\",\"id\":2659,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"51708d5\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>V\\u1ec9 m\\u1ea1ch \\u0111o v\\u00e0 hi\\u1ec3n th\\u1ecb t\\u1ed1c \\u0111\\u1ed9 m\\u00e1y t\\u00e0u thu\\u1ef7 c\\u00f3 ch\\u1ee9c n\\u0103ng \\u0111o, t\\u00ednh to\\u00e1n v\\u00e0 hi\\u1ec3n th\\u1ecb t\\u1ed1c \\u0111\\u1ed9 m\\u00e1y \\u0111\\u00e8n v\\u00e0 m\\u00e1y ch\\u00ednh tr\\u00ean t\\u00e0u thu\\u1ef7 v\\u1edbi c\\u00e1c \\u0111\\u1eb7c \\u0111i\\u1ec3m:<\\/p><p>- D\\u1ec5 d\\u00e0ng l\\u1eafp \\u0111\\u1eb7t v\\u00e0 k\\u1ebft n\\u1ed1i,<\\/p><p>- C\\u00f3 \\u0111\\u1ea7u ra cho vi\\u1ec7c b\\u00e1o \\u0111\\u1ed9ng qu\\u00e1 t\\u1ed1c,<\\/p><p>- Cho ph\\u00e9p l\\u1ef1a ch\\u1ecdn c\\u00e0i \\u0111\\u1eb7t c\\u00e1c tham s\\u1ed1 \\u0111\\u1ea7u v\\u00e0o nh\\u01b0 s\\u1ed1 xung tr\\u00ean m\\u1ed9t v\\u00f2ng quay, tham s\\u1ed1 qu\\u00e1 t\\u1ed1c, th\\u1eddi gian l\\u1ea5y m\\u1eabu<\\/p><p>- C\\u00f3 \\u0111\\u1ea7u ra \\u00b1 10v cho ph\\u00e9p k\\u1ebft n\\u1ed1i v\\u1edbi \\u0111\\u1ed3ng h\\u1ed3 ch\\u1ec9 b\\u00e1o b\\u1eb1ng kim<\\/p><p><em>3. V\\u1ec9 m\\u1ea1ch b\\u00e1o \\u0111\\u1ed9ng c\\u00e1c th\\u00f4ng s\\u1ed1<\\/em><\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"2c385b9\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/vi-mach-3.jpg\",\"id\":2660,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"de29692\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>V\\u1ec9 m\\u1ea1ch b\\u00e1o \\u0111\\u1ed9ng c\\u00e1c th\\u00f4ng s\\u1ed1 c\\u00f3 ch\\u1ee9c n\\u0103ng \\u0111o v\\u00e0 b\\u00e1o \\u0111\\u1ed9ng c\\u00e1c th\\u00f4ng s\\u1ed1 trong bu\\u1ed3ng m\\u00e1y v\\u1edbi c\\u00e1c \\u0111\\u1eb7c \\u0111i\\u1ec3m sau:<\\/p><ul><li>Cho ph\\u00e9p \\u0111o v\\u00e0 b\\u00e1o \\u0111\\u1ed9ng \\u0111\\u1ed3ng th\\u1eddi 15 k\\u00eanh<\\/li><li>Chu k\\u1ef3 v\\u00e0 d\\u1ea1ng t\\u00edn hi\\u1ec7u b\\u00e1o \\u0111\\u1ed9ng c\\u1ee7a 15 k\\u00eanh ri\\u00eang r\\u1ebd c\\u00f3 th\\u1ec3 c\\u00e0i \\u0111\\u1eb7t \\u0111\\u01b0\\u1ee3c b\\u1eb1ng m\\u00e1y t\\u00ednh<\\/li><li>D\\u00f2ng ra c\\u1ef1c \\u0111\\u1ea1i c\\u1ee7a m\\u1ed9t k\\u00eanh l\\u00e0 500mA, 24vdc<\\/li><\\/ul>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"f4441ef\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/vi-mach-4.jpg\",\"id\":2661,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"f4c2693\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p><em>4. V\\u1ec9 m\\u1ea1ch ngh\\u00e9p n\\u1ed1i tay chu\\u00f4ng truy\\u1ec1n l\\u1ec7nh \\u2013 VDR<\\/em><\\/p><p>V\\u1ec9 m\\u1ea1ch gh\\u00e9p n\\u1ed1i tay chu\\u00f4ng truy\\u1ec1n l\\u1ec7nh \\u2013 VDR c\\u00f3 ch\\u1ee9c n\\u0103ng chuy\\u1ec3n \\u0111\\u1ed5i c\\u00e1c l\\u1ec7nh d\\u01b0\\u1edbi d\\u1ea1ng ON\\/OFF c\\u1ee7a h\\u1ec7 th\\u1ed1ng tay chu\\u00f4ng truy\\u1ec1n l\\u1ec7nh th\\u00e0nh c\\u00e1c c\\u00e2u l\\u1ec7nh \\u0111\\u01b0\\u1ee3c \\u0111\\u01b0\\u1ee3c \\u0111\\u00f3ng theo giao th\\u1ee9c NMEA0183 sau \\u0111\\u00f3 truy\\u1ec1n th\\u00f4ng sang h\\u1ec7 th\\u1ed1ng h\\u1ed9p \\u0111en. V\\u1ec9 m\\u1ea1ch c\\u00f3 th\\u1ec3 chuy\\u1ec3n \\u0111\\u1ed5i \\u0111\\u01b0\\u1ee3c t\\u1ea5t c\\u1ea3 c\\u00e1c l\\u1ec7nh c\\u01a1 b\\u1ea3n c\\u1ee7a h\\u1ec7 th\\u1ed1ng tay chu\\u00f4ng truy\\u1ec1n l\\u1ec7nh sang chu\\u1ea9n truy\\u1ec1n d\\u1eef li\\u1ec7u NMEA 0183<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"