"settings\":{\"text\":\"Li\\u00ean h\\u1ec7\",\"align\":\"center\",\"typography_font_weight\":\"normal\",\"__globals__\":{\"button_text_color\":\"\",\"background_color\":\"\",\"button_background_hover_color\":\"\"},\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"typography_font_size_mobile\":{\"unit\":\"px\",\"size\":14,\"sizes\":[]},\"typography_typography\":\"custom\",\"typography_text_transform\":\"uppercase\",\"_margin\":{\"unit\":\"px\",\"top\":\"25\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"background_background\":\"\",\"button_background_hover_background\":\"\",\"link\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/contact\\/\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"typography_font_size\":{\"unit\":\"px\",\"size\":42,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false}]'),
