(5373, 3023, '_elementor_data', '[{\"id\":\"eb4fbc9\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\"},\"elements\":[{\"id\":\"d9c0896\",\"elType\":\"widget\",\"settings\":{\"title\":\"C\\u1ee5c \\u0110\\u0103ng ki\\u1ec3m Vi\\u1ec7t Nam ch\\u00ednh th\\u1ee9c c\\u1ea5p gi\\u1ea5y ch\\u1ee9ng nh\\u1eadn ki\\u1ec3u cho version 2 H\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd n\\u01b0\\u1edbc d\\u1eb1n TLC-BWM\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"6ee3c83\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Ng\\u00e0y 10 th\\u00e1ng 9 n\\u0103m 2020, C\\u1ee5c \\u0110\\u0103ng ki\\u1ec3m Vi\\u1ec7t Nam \\u0111\\u00e3 c\\u1ea5p gi\\u1ea5y ch\\u1ee9ng nh\\u1eadn c\\u00f4ng nh\\u1eadn ki\\u1ec3u (S\\u1ed1 ch\\u1ee9ng ch\\u1ec9: 00437\\/20CN01.TA) cho h\\u1ec7 th\\u1ed1ng qu\\u1ea3n l\\u00fd n\\u01b0\\u1edbc d\\u1eb1n \\u0111\\u01b0\\u1ee3c ph\\u00e1t tri\\u1ec3n b\\u1edfi c\\u00f4ng ty TNHH Ph\\u00e1t tri\\u1ec3n c\\u00f4ng ngh\\u1ec7 h\\u00e0ng h\\u1ea3i Th\\u1ea3o Linh.<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"e260910\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/1-1-1.jpg\",\"id\":2564,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":false}]'),
