INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(6077, 3076, '_elementor_data', '[{\"id\":\"d5f659d\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\"},\"elements\":[{\"id\":\"c3e65d5\",\"elType\":\"widget\",\"settings\":{\"title\":\"T\\u00e0u bi\\u1ec3n ch\\u1ea1y b\\u1eb1ng s\\u1ee9c gi\\u00f3\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"3d0587a\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<div class=\\\"brief_news_page\\\"><p><strong>H\\u00e3ng \\u0111\\u00f3ng t\\u00e0u Lade AS (Na Uy) v\\u1eeba cho bi\\u1ebft, h\\u1ecd \\u0111ang thi\\u1ebft k\\u1ebf m\\u1ed9t con t\\u00e0u bi\\u1ec3n ch\\u1ea1y b\\u1eb1ng s\\u1ee9c gi\\u00f3 c\\u00f3 t\\u00ean l\\u00e0 Vindskip hay c\\u00f2n g\\u1ecdi l\\u00e0 t\\u00e0u bi\\u1ec3n lai (hybrid), v\\u1eeba ch\\u1ea1y b\\u1eb1ng n\\u0103ng l\\u01b0\\u1ee3ng truy\\u1ec1n th\\u1ed1ng l\\u1ea1i c\\u00f3 th\\u1ec3 ch\\u1ea1y \\u0111\\u01b0\\u1ee3c b\\u1eb1ng n\\u0103ng l\\u01b0\\u1ee3ng gi\\u00f3.<\\/strong><\\/p><p>\\u00a0<\\/p><\\/div><div class=\\\"content_news_page\\\"><p>Theo h\\u00e3ng Lade AS, tuy kh\\u00f4ng ch\\u1ea1y b\\u1eb1ng 100% n\\u0103ng l\\u01b0\\u1ee3ng gi\\u00f3, nh\\u01b0ng Vindskip c\\u00f3 th\\u1ec3 ti\\u1ebft ki\\u1ec7m \\u0111\\u01b0\\u1ee3c t\\u1edbi 60% nhi\\u00ean li\\u1ec7u so v\\u1edbi t\\u00e0u c\\u00f9ng k\\u00edch th\\u01b0\\u1edbc v\\u00e0 gi\\u1ea3m \\u0111\\u01b0\\u1ee3c t\\u1edbi 80% m\\u1ee9c ph\\u00e1t t\\u00e1n kh\\u00ed th\\u1ea3i.<\\/p><p>\\u00d4ng Terje Lade - Gi\\u00e1m \\u0111\\u1ed1c Lade AS cho bi\\u1ebft, nh\\u00f3m nghi\\u00ean c\\u1ee9u \\u0111\\u00e3 l\\u1ea5y c\\u1ea3m h\\u1ee9ng t\\u1eeb ng\\u00e0nh C\\u00f4ng nghi\\u1ec7p h\\u00e0ng kh\\u00f4ng v\\u0169 tr\\u1ee5 \\u0111\\u1ec3 t\\u1ea1o ra m\\u1ed9t th\\u00e2n t\\u00e0u gi\\u1ed1ng nh\\u01b0 hai c\\u00e1nh \\u0111\\u1ed1i x\\u1ee9ng c\\u1ee7a m\\u00e1y bay.<\\/p><p>M\\u00f4 h\\u00ecnh thi\\u1ebft k\\u1ebf ki\\u1ec3u n\\u00e0y gi\\u00fap khai th\\u00e1c t\\u1ed1c \\u0111\\u1ed9 l\\u1ef1c n\\u00e2ng \\u0111\\u1ed9ng h\\u1ecdc, gi\\u00fap t\\u00e0u di chuy\\u1ec3n thu\\u1eadn l\\u1ee3i. \\u0110\\u1eb7c bi\\u1ec7t, m\\u00f4 h\\u00ecnh theo c\\u00e1nh m\\u00e1y bay \\u0111\\u1ed1i x\\u1ee9ng s\\u1ebd \\u0111\\u1ea3m b\\u1ea3o n\\u00e2ng t\\u00e0u l\\u00ean khi c\\u00f3 gi\\u00f3 \\u0111\\u1ebfn t\\u1eeb m\\u1ea1n b\\u00ean v\\u00e0 t\\u1eeb ph\\u00eda tr\\u01b0\\u1edbc. N\\u00f3i c\\u1ee5 th\\u1ec3 h\\u01a1n, nguy\\u00ean l\\u00fd ch\\u1ebf ng\\u1ef1 s\\u1ee9c gi\\u00f3 c\\u1ee7a Vindskip gi\\u1ed1ng nh\\u01b0 hai c\\u00e1nh m\\u00e1y bay \\u0111\\u1ed1i x\\u1ee9ng ho\\u1eb7c c\\u00e1nh bu\\u1ed3m.\\u00a0<\\/p><p>Ngo\\u00e0i thi\\u1ebft k\\u1ebf n\\u00f3i tr\\u00ean, c\\u00e1c chuy\\u00ean gia Lade AS c\\u00f2n s\\u1eed d\\u1ee5ng h\\u1ec7 th\\u1ed1ng \\u0111\\u1ecbnh v\\u1ecb \\u0111\\u1ec3 c\\u1eadp nh\\u1eadt d\\u1eef li\\u1ec7u, t\\u1eadn d\\u1ee5ng t\\u1ed1i \\u0111a th\\u1ebf m\\u1ea1nh th\\u1eddi ti\\u1ebft nh\\u1eb1m gi\\u00fap t\\u00e0u v\\u1eadn h\\u00e0nh \\u0111\\u1ea1t hi\\u1ec7u qu\\u1ea3 cao h\\u01a1n.<\\/p><p>Ngo\\u00e0i ra, Vindskip c\\u00f2n s\\u1eed d\\u1ee5ng m\\u1ed9t \\u0111\\u1ed9ng c\\u01a1 \\u0111i\\u1ec7n ch\\u1ea1y b\\u1eb1ng kh\\u00ed t\\u1ef1 nhi\\u00ean \\u0111\\u1ec3 ho\\u1ea1t \\u0111\\u1ed9ng c\\u00e1c ph\\u1ea7n c\\u00f2n l\\u1ea1i c\\u1ee7a t\\u00e0u v\\u00e0 s\\u1eed d\\u1ee5ng khi tr\\u1eddi kh\\u00f4ng c\\u00f3 gi\\u00f3.<\\/p><\\/div>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"ae5abce\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/thaolinhmateco\\/wp-content\\/uploads\\/2026\\/03\\/10.jpg\",\"id\":2629,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":false}]'),
