INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `condition_id`, `priority`, `active`, `modified`, `revision`, `cloud_id`) VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\' );', 'sample, media', 'global', 0, 10, 0, '2026-03-26 16:12:27', 1, NULL),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 0, 10, 0, '2026-03-26 16:12:27', 1, NULL),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );', 'sample', 'global', 0, 10, 0, '2026-03-26 16:12:27', 1, NULL),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( \'Y\' ); ?>', 'sample, dates', 'content', 0, 10, 0, '2026-03-26 16:12:27', 1, NULL),
(5, 'Sản phẩm', '', 'add_shortcode(\'san_pham_tu_code\', \'lay_du_lieu_san_pham_thaolinh\');\n\nfunction lay_du_lieu_san_pham_thaolinh() {\n    // 1. Thông tin kết nối\n    $servername = \"localhost\";\n    $username = \"root\"; \n    $password = \"\";     \n    $dbname = \"mateco_csdl\";\n\n    // Tạo kết nối\n    $conn = new mysqli($servername, $username, $password, $dbname);\n\n    // Kiểm tra kết nối\n    if ($conn->connect_error) {\n        return \"Kết nối thất bại: \" . $conn->connect_error;\n    }\n\n    // Set charset utf8mb4 để hiển thị tiếng Việt chuẩn\n    $conn->set_charset(\"utf8mb4\");\n\n    // 2. Viết câu lệnh SQL lấy dữ liệu\n    $sql = \"SELECT * FROM sanpham\";\n    $result = $conn->query($sql);\n\n    // 3. Xây dựng giao diện dạng Lưới (Grid)\n    $html = \'<div style=\"display: flex; flex-wrap: wrap; gap: 20px; justify-content: center; padding: 20px;\">\';\n\n    if ($result->num_rows > 0) {\n        // Lặp qua từng sản phẩm\n        while($row = $result->fetch_assoc()) {\n            $html .= \'<div style=\"border: 1px solid #e0e0e0; border-radius: 8px; padding: 15px; width: 260px; background: #fff; box-shadow: 0 4px 8px rgba(0,0,0,0.05); display: flex; flex-direction: column; align-items: center; text-align: center;\">\';\n            \n            // Hiển thị Hình ảnh\n            if (!empty($row[\"HinhAnh\"])) {\n                $html .= \'<img src=\"\' . esc_url($row[\"HinhAnh\"]) . \'\" alt=\"Ảnh sản phẩm\" style=\"width: 100%; height: 200px; object-fit: contain; margin-bottom: 15px;\" />\';\n            }\n\n            // Hiển thị Tên sản phẩm\n            $html .= \'<h3 style=\"font-size: 16px; color: #003366; margin: 0 0 10px 0; min-height: 48px; line-height: 1.4;\">\' . esc_html($row[\"TenSanPham\"]) . \'</h3>\';\n            \n            // Hiển thị Mã loại sản phẩm\n            $html .= \'<span style=\"background: #f1f2f6; padding: 4px 10px; border-radius: 4px; font-size: 12px; margin-bottom: 10px; color: #555;\">Mã loại: \' . esc_html($row[\"MaLoaiSanPham\"]) . \'</span>\';\n\n            // Hiển thị Giá\n            $html .= \'<p style=\"color: #e74c3c; font-weight: bold; font-size: 18px; margin: 0;\">\' . number_format($row[\"Gia\"], 0, \',\', \'.\') . \' VNĐ</p>\';\n            \n            // --- XỬ LÝ ĐƯỜNG DẪN NÚT BẤM ---\n            \n            // Link sản phẩm (dựa trên slug tên sản phẩm)\n            $slug_san_pham = sanitize_title($row[\"TenSanPham\"]);\n            $link_san_pham = home_url(\'/chi-tiet-san-pham/\' . $slug_san_pham . \'/\');\n            \n            // Link Giỏ hàng (đúng cấu trúc localhost/thaolinhmateco/gio-hang/)\n            $id_sp = $row[\"MaSanPham\"]; \n			$link_gio_hang = \'/thaolinhmateco/gio-hang/?add_to_cart=\' . $id_sp;\n            \n            // Hiển thị 2 nút bấm nằm ngang\n            $html .= \'<div style=\"display: flex; gap: 8px; margin-top: 15px; width: 100%; justify-content: center;\">\';\n                \n                // Nút Xem mô tả\n                $html .= \'<a href=\"\' . esc_url($link_san_pham) . \'\" style=\"flex: 1; padding: 8px 5px; background-color: #2980b9; color: #ffffff; text-decoration: none; border-radius: 4px; font-weight: bold; font-size: 12px; text-align: center;\">Xem mô tả</a>\';\n                \n                // Nút Thêm vào giỏ\n                $html .= \'<a href=\"\' . esc_url($link_gio_hang) . \'\" style=\"flex: 1; padding: 8px 5px; background-color: #27ae60; color: #ffffff; text-decoration: none; border-radius: 4px; font-weight: bold; font-size: 12px; text-align: center;\">Thêm vào giỏ</a>\';\n\n            $html .= \'</div>\';\n\n            $html .= \'</div>\';\n        }\n    } else {\n        $html .= \"<p>Chưa có sản phẩm nào trong bảng sanpham.</p>\";\n    }\n    \n    $html .= \'</div>\';\n\n    // Đóng kết nối database\n    $conn->close();\n\n    return $html;\n}', '', 'global', 0, 10, -1, '2026-03-30 03:15:22', 1, NULL),
(6, 'Tin tức', '', 'add_shortcode(\'tin_tuc_tu_code\', \'lay_du_lieu_tin_tuc_thaolinh\');\n\nfunction lay_du_lieu_tin_tuc_thaolinh() {\n    // 1. Thông tin kết nối\n    $servername = \"localhost\";\n    $username = \"root\"; \n    $password = \"\";     \n    $dbname = \"mateco_csdl\";\n\n    // Tạo kết nối\n    $conn = new mysqli($servername, $username, $password, $dbname);\n\n    // Kiểm tra kết nối\n    if ($conn->connect_error) {\n        return \"Kết nối thất bại: \" . $conn->connect_error;\n    }\n\n    // Set charset utf8mb4\n    $conn->set_charset(\"utf8mb4\");\n\n    // 2. Viết câu lệnh SQL lấy dữ liệu\n    $sql = \"SELECT * FROM tintuc ORDER BY NgayDang DESC\";\n    $result = $conn->query($sql);\n\n    // 3. Xây dựng giao diện dạng Lưới (Grid)\n    $html = \'<div style=\"display: flex; flex-wrap: wrap; gap: 20px; justify-content: center; font-family: Arial, sans-serif;\">\';\n\n    if ($result->num_rows > 0) {\n        while($row = $result->fetch_assoc()) {\n            $html .= \'<div style=\"border: 1px solid #e0e0e0; border-radius: 8px; padding: 15px; width: 300px; background: #fff; box-shadow: 0 4px 8px rgba(0,0,0,0.05); display: flex; flex-direction: column; text-align: left;\">\';\n            \n            // Xử lý Hình ảnh\n            $hinhAnh = $row[\"HinhAnh\"];\n            $hinhAnhUrl = \'\';\n            if (!empty($hinhAnh)) {\n                if (preg_match(\'/src=\"([^\"]+)\"/\', $hinhAnh, $match)) {\n                    $hinhAnhUrl = $match[1];\n                } else {\n                    $hinhAnhUrl = $hinhAnh;\n                }\n                $html .= \'<img src=\"\' . esc_url($hinhAnhUrl) . \'\" alt=\"\' . esc_attr($row[\"Title\"]) . \'\" style=\"width: 100%; height: 180px; object-fit: cover; border-radius: 4px; margin-bottom: 15px;\" />\';\n            }\n\n            // Hiển thị Tiêu đề (Title)\n            $html .= \'<h3 style=\"font-size: 18px; color: #003366; margin: 0 0 10px 0; line-height: 1.4; height: 50px; overflow: hidden;\">\' . esc_html($row[\"Title\"]) . \'</h3>\';\n            \n            // Hiển thị Ngày đăng\n            $ngayDang = date(\"d/m/Y\", strtotime($row[\"NgayDang\"]));\n            $html .= \'<span style=\"font-size: 13px; color: #7f8c8d; margin-bottom: 10px; display: block;\">⏳ \' . esc_html($ngayDang) . \'</span>\';\n\n            // Hiển thị Mô tả ngắn\n            $html .= \'<p style=\"color: #555; font-size: 14px; margin: 0; line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; flex-grow: 1;\">\' . esc_html($row[\"MoTaNgan\"]) . \'</p>\';\n            \n            // --- PHẦN THAY ĐỔI: TẠO LINK XEM CHI TIẾT THEO SLUG ---\n            // sanitize_title sẽ chuyển \"Hệ thống TLC-BWM\" thành \"he-thong-tlc-bwm\"\n            $slug = sanitize_title($row[\"Title\"]);\n            $link_chi_tiet = home_url(\'/tin-tuc/\' . $slug . \'/\');\n            \n            $html .= \'<a href=\"\' . esc_url($link_chi_tiet) . \'\" style=\"display: inline-block; margin-top: 15px; padding: 10px 16px; background-color: #3498db; color: #ffffff; text-decoration: none; border-radius: 4px; font-weight: bold; font-size: 14px; text-align: center; transition: background 0.3s;\">Xem chi tiết</a>\';\n            // ----------------------------------------------------\n\n            $html .= \'</div>\';\n        }\n    } else {\n        $html .= \"<p>Chưa có bài viết nào.</p>\";\n    }\n    \n    $html .= \'</div>\';\n    $conn->close();\n    return $html;\n}', '', 'global', 0, 10, -1, '2026-03-27 02:02:39', 1, NULL),
(7, 'functions', '', '', '', 'global', 0, 10, -1, '2026-04-07 14:36:16', 1, NULL),
